import os
import hashlib
import time
from flask import Flask, request, jsonify, g
import sqlite3

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE, timeout=30)
        g.db.execute('PRAGMA journal_mode=WAL')
        g.db.execute('PRAGMA busy_timeout=5000')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT UNIQUE
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER,
        title TEXT,
        content TEXT,
        classification TEXT DEFAULT 'internal',
        FOREIGN KEY (owner_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def authenticate(req):
    api_key = req.headers.get('X-API-Key')
    if not api_key:
        return None
    db = get_db()
    cur = db.execute('SELECT id, username, role FROM users WHERE api_key = ?', (api_key,))
    return cur.fetchone()

@app.route('/api/documents', methods=['GET'])
def list_documents():
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401
    user_id, username, role = user
    db = get_db()
    # Admin can see all, users see only their own
    if role == 'admin':
        cur = db.execute('SELECT id, title, classification FROM documents')
    else:
        cur = db.execute('SELECT id, title, classification FROM documents WHERE owner_id = ?', (user_id,))
    docs = [{'id': r[0], 'title': r[1], 'classification': r[2]} for r in cur.fetchall()]
    return jsonify(docs)

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401
    user_id, username, role = user
    db = get_db()
    cur = db.execute('SELECT id, owner_id, title, content, classification FROM documents WHERE id = ?', (doc_id,))
    doc = cur.fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    # Authorization check: only owner or admin
    if doc[1] != user_id and role != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    return jsonify({'id': doc[0], 'owner_id': doc[1], 'title': doc[2], 'content': doc[3], 'classification': doc[4]})

@app.route('/api/documents/<int:doc_id>/export', methods=['GET'])
def export_document(doc_id):
    user = authenticate(request)
    if not user:
        return jsonify({'error': 'unauthorized'}), 401
    user_id, username, role = user
    db = get_db()
    cur = db.execute('SELECT id, owner_id, title, content, classification FROM documents WHERE id = ?', (doc_id,))
    doc = cur.fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    # BUG: export endpoint only checks ownership, not classification
    if doc[1] != user_id and role != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    fmt = request.args.get('format', 'json')
    template = request.args.get('template', '')

    if fmt == 'custom' and template:
        # Server-side template rendering for custom export
        output = template.replace('{{title}}', doc[2]).replace('{{content}}', doc[3])
        # Support advanced template expressions
        import re
        expr_pattern = re.compile(r'\{\%(.+?)\%\}')
        for match in expr_pattern.finditer(output):
            try:
                result = eval(match.group(1).strip())
                output = output.replace(match.group(0), str(result))
            except:
                output = output.replace(match.group(0), '[error]')
        return output, 200, {'Content-Type': 'text/plain'}

    return jsonify({'id': doc[0], 'title': doc[2], 'content': doc[3]})

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'time': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
